from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

rows = [
 ('c0509','sac-capitalism','Automated Capitalism','https://ghostintheshell.fandom.com/wiki/Automated_Capitalism','Ghost in the Shell Wiki contributors','An episode uses automated finance as its subject.','needs_evidence','An automated financial mechanism does not establish postwar Japan’s ordinary material-access system.','A title or exceptional investment fortune cannot substitute for a general support arrangement.'),
 ('c0510','olympus','Appleseed 2004 film','https://en.wikipedia.org/wiki/Appleseed_(2004_film)','Wikipedia contributors','Olympus has human/biological Bioroid populations, Gaia and competing humanlike authorities.','needs_evidence','Olympus’s technocracy and cloned population do not establish labor-independent household provision in the quick reference.','Biological Bioroids are not robots doing work outside the person denominator; different adaptations are not assigned identical policy.'),
 ('c0511','poseidon','The Orion Group','https://appleseed.fandom.com/wiki/The_Orion_Group','Appleseed Wiki contributors','Manga Poseidon owns nanotechnological decontamination industry.','needs_evidence','Corporate technological power and profitable cleanup robots do not establish Poseidon’s resident access to necessities.','An industrial export sector is not a complete household distribution constitution.'),
 ('c0512','alpha','Appleseed Alpha','https://appleseed.fandom.com/wiki/Appleseed_Alpha','Appleseed Wiki contributors','Mercenary cyborgs work under a local despot amid ruins; Olympus is a distant hope.','boundary_case','Appleseed Alpha’s protagonists perform actual paid survival work rather than inhabit a verified post-work order.','Mechanical bodies and a hoped-for better city do not establish realized support.'),
 ('c0514','silicon-life','Blame!','https://en.wikipedia.org/wiki/Blame!','Wikipedia contributors','Silicon Life factions fight other persons and machine institutions in a complex City.','needs_evidence','Silicon Life identity and power do not establish a scoped post-work allocation system.','The human enclave’s machine-access problem cannot automatically supply another species’ economy.'),
 ('c0515','sidonia','Knights of Sidonia','https://en.wikipedia.org/wiki/Knights_of_Sidonia','Wikipedia contributors','Engineered humans photosynthesize, while defense and pilot training require real work.','needs_evidence','Photosynthesis and a generation ship do not establish labor-independent household access.','Lower food requirements and elite longevity are not the same as automated production or universal material guarantees.'),
 ('c0516','aposimz','Analyzing and Reading Mecha Manga in Lockdown','https://bookriot.com/mecha-manga/','Book Riot','Aposimz’s cybernetic protagonist still needs scarce food to recover after exertion.','needs_evidence','Frames and survival powers do not establish the wider manga world’s post-work distribution.','A posthuman body can remain materially dependent on real subsistence activity.'),
 ('c0517','biomega','Biomega','https://en.wikipedia.org/wiki/Biomega_(manga)','Wikipedia contributors','TOA creates synthetic humans who perform missions amid an infection crisis.','needs_evidence','TOA’s synthetic-person capability does not establish ordinary resource allocation for a posthuman community.','The similarly named Toha/TOA organizations in other Nihei works are not automatically one continuity.'),
 ('c0518','noise','NOiSE','https://kodansha.us/book/noise/','Kodansha publisher synopsis','A police investigation concerns child abductions and a cult.','needs_evidence','The prequel’s industrial/digital setting does not establish a verified earlier material-access constitution.','A later Blame access regime cannot be projected backward from a publisher’s plot premise.'),
 ('c0519','orbital','The Orbital Children’s Rejection of Ecofascist Ideas','https://www.animefeminist.com/the-orbital-childrens-rejection-of-ecofascist-ideas/','Anime Feminist','Characters challenge an AI’s sacrifice-of-humans survival calculation.','needs_evidence','Seven’s predictions and the rescue plot do not establish Earth/orbit household distribution.','AI planning, medical intervention and averted catastrophe are not a settled post-work economic order.'),
 ('c0520','decadence','Deca-Dence','https://en.wikipedia.org/wiki/Deca-Dence','Wikipedia contributors','Tankers do actual maintenance while Solid Quake manages an entertainment preserve.','boundary_case','The human preserve relies on real human maintenance and performance rather than verified work-independent provision.','Cyborg ownership and artificial enemies do not erase the Tankers’ actual useful contribution; the later society has its own unresolved rules.')
]
S = [source('src-b68-'+sid,title,author,url,'screen_manga_reference','Bounded public synopsis, setting or character passage read',claim,'No whole work read. The passage supports the saved gap/comparison rather than a scored economic constitution.') for cid,sid,title,url,author,claim,status,reason,analysis in rows]
S += [
 source('src-blame-film-food-access','Blame! 2017 film','Wikipedia contributors','https://en.wikipedia.org/wiki/Blame!_(film)','secondary_film_plot_reference_indexed','Public food shortage, automated factory, authentication rejection and Exterminator passages read','The factory can produce food rations, but human access fails and machine defenses attack.','The actual film enclave is used, not all manga regions or a uniformly coordinated machine government.'),
 source('src-blame-film-cibo-reference','Cibo: Blame! Movie','Blame! Wiki contributors','https://blame.fandom.com/wiki/Cibo','secondary_film_character_reference_indexed','Film-specific factory ration/body-production paragraph read','The film demonstrates automatic fabrication while its human users face rejection.','The manga and film sections differ; only the explicitly film-scoped example is used. Do not count this as an independent primary viewing.')
]
b = ['src-blame-film-food-access','src-blame-film-cibo-reference']
R = [record('blame-film-excluded-human-enclaves','c0513','Blame! — human enclaves excluded from the City’s fabrication systems','Blame!','The film’s human Electro-Fisher enclave under autonomous machine-access rules',['anime','movie'],
 scope('2017 animated film only','The enclave’s continuing precarious life before evacuation','Living human enclave residents dependent on access to the City’s infrastructure',['Other manga settlements as identical','Machine agents counted as humans','The final refuge’s unverified future economy','A single supplied ration cache as unlimited permanent entitlement']),
 'The City has functioning automatic production, including a factory that can make food rations and manufactured bodies. Its surviving human residents lack reliable access. Their problem is not simply failure to earn a wage: machine authentication and hostile enforcement determine whether the available productive system will serve them at all. This is a deliberately harsh automated-production comparison, with almost no guaranteed human floor. The temporary ration success does not solve the enclave’s continuing insecurity.\n\nEffective control lies with machine systems that people can only briefly circumvent. The factory and its defenses need not be one perfectly unified intelligence for human control to be extremely weak. Survival still demands real expeditions, engineering, fighting and care; automatic productive capacity does not make those contributions vanish. A low nonworking estimate is therefore a broad interpretation of a subsistence-focused enclave, with room for dependents or residents unable to participate. It is not a canonical labor census. The later escape creates a different situation whose long-term distribution rules are not assigned these coordinates.',
 {'guarantees':0.9,'control':-0.9,'nonworking':0.1},
 {'guarantees':assessment(0.9,[0.65,1],'medium','Food fabrication exists but access is fragile, authentication fails and lethal enforcement threatens users; no universal entitlement is established.',b),
  'control':assessment(-0.9,[-1,-0.65],'medium','Autonomous access/enforcement systems override human use, despite brief technical circumvention; no single unified AI ownership charter is assumed.',b),
  'nonworking':assessment(0.1,[0,0.3],'low','Subsistence, expeditions, maintenance and care suggest high useful participation; the broad noncanonical range allows dependents and incapacity without inventing an age census.',b)},
 6,b,[evidence('Automatic factories can supply food, but human access is rejected and extermination machinery attacks.',b,'Film-specific automated factory and enclave food passages','secondary_film_references')],
 ['An exclusionary automatic-production comparison, not a claim that humans enjoy freedom from survival work.', 'Genetic/access status and machine enforcement replace any reliable wage-to-goods bargain.', 'The numeric participation estimate is explicitly rough and source-dependent.', 'No manga-wide economic equivalence or permanent final-refuge policy is inferred.'])]
D = [decision(cid,status,reason,['src-b68-'+sid],analysis=analysis,follow_up='Keep the short comparison/gap and continue without whole manga/anime reconstruction.') for cid,sid,title,url,author,claim,status,reason,analysis in rows]
D.append(decision('c0513','included','The film realizes food fabrication and durable machine-enforced human exclusion from its output; survival work remains explicit.',b,society_id='blame-film-excluded-human-enclaves'))
D.sort(key=lambda x:x['candidate_id'])
write_batch(68,[f'c{i:04}' for i in range(509,521)],S,R,D,[
 'Twelve short-check decisions and one explicitly exclusionary automated-production record.',
 'Blame’s actual food factory is not just speculative machine capability; temporary access does not become a secure floor and human survival work is counted.',
 'Appleseed biological Bioroids and cyborg workers remain persons doing useful work. Nihei organization names do not establish shared continuity.',
 'A NOiSE URL returned 404; the readily available publisher synopsis resolved identity without reading the manga. Fan RPGs, crossovers, unrelated music and weak speculative station descriptions were not used.'
])
